+		ScannedCves: models.VulnInfos{
+			"resolved": {CveID: "resolved", AffectedPackages: models.PackageFixStatuses{{Name: "old"}}},
+			"shared":   {CveID: "shared"},
+		},
+		Packages: models.Packages{"old": {Name: "old", Version: "previous"}},
+	}
+	current := models.ScanResult{
+		ServerName: "host",
+		ScannedCves: models.VulnInfos{
+			"new":    {CveID: "new", AffectedPackages: models.PackageFixStatuses{{Name: "new"}}},
+			"shared": {CveID: "shared"},
+		},
+		Packages: models.Packages{"new": {Name: "new", Version: "current"}},
+	}
+	for _, tc := range []struct {
+		plus, minus         bool
+		wantPlus, wantMinus int
+	}{
+		{true, false, 1, 0},
+		{false, true, 0, 1},
+		{true, true, 1, 1},
+		{false, false, 0, 0},
+	} {
+		results, err := diff(models.ScanResults{current}, models.ScanResults{previous}, tc.plus, tc.minus)
+		if err != nil {
+			t.Fatal(err)
+		}
+		got := results[0]
+		p, m := got.ScannedCves.CountDiff()
+		if p != tc.wantPlus || m != tc.wantMinus || len(got.ScannedCves) != p+m {
+			t.Errorf("plus=%t minus=%t: got %d additions, %d removals, %d total", tc.plus, tc.minus, p, m, len(got.ScannedCves))
