+				t.Error("addition status or package source incorrect")
+			}
+		}
+		if tc.minus {
+			if got.ScannedCves["resolved"].DiffStatus != models.DiffMinus || got.Packages["old"].Version != "previous" {
+				t.Error("removal status or package source incorrect")
+			}
+		}
+	}
